			// Note: J and K_bar are assumed to be connected together.module SReg_74195 (  output reg QA, QB, QC, QD,   output QD_bar,   input A, B, C, D, SH_LD, J, K_bar, CLR_bar, CK);  assign QD_bar = ~QD;  always @ (posedge CK, negedge CLR_bar)    if (!CLR_bar) {QA, QB, QC, QD} <= 4'b0;    else if (!SH_LD) {QA, QB, QC, QD} <= {A, B, C, D};    else case ({J, K_bar})      2'b00: 	{QA, QB, QC, QD} <= {1'b0, QA, QB, QC};      2'b11: 	{QA, QB, QC, QD} <= {1'b1, QA, QB, QC};	      2'b01:	{QA, QB, QC, QD} <= {QA, QA, QB, QC};	// unused      2'b10:	{QA, QB, QC, QD} <= {~QA, QA, QB, QC};	// unused    endcaseendmodulemodule t_SReg_74195 ();  wire QA, QB, QC, QD;   wire QD_bar;  reg A, B, C, D, SH_LD, CLR_bar, CK;  reg	Serial_Input;  wire J = Serial_Input;  wire K_bar = Serial_Input;  wire [3: 0] Data_inputs = {A, B, C, D};  wire [3: 0] Data_outputs = {QA, QB, QC, QD};  SReg_74195 M0 (QA, QB, QC, QD, QD_bar, A, B, C, D, SH_LD, J, K_bar, CLR_bar, CK);  initial #200 $finish;  initial begin CK = 0; forever #5 CK = ~CK; end  initial fork    {A, B, C, D} = 4'ha;    CLR_bar = 0;    Serial_Input = 0;    SH_LD = 0;    #30 CLR_bar = 1;    #60 SH_LD = 1;    #120 Serial_Input = 1;  joinendmodule